    "org_id" bigint NOT NULL,
    "value_hash" varchar(64) NOT NULL,
    "value" text DEFAULT NULL,
    "module" varchar(100) NOT NULL,
    "type" varchar(100) NOT NULL,
    "state" varchar(32) NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "last_run" bigint DEFAULT 0 NOT NULL,
    "took" integer DEFAULT 0 NOT NULL,
    "total" integer DEFAULT 0 NOT NULL,
    "shown" integer DEFAULT 0 NOT NULL,
    "capped" boolean DEFAULT 'FALSE' NOT NULL,
    "message" text DEFAULT NULL,
    "result" bytea DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "idx_value_enrichment_runs_last_run" ON "value_enrichment_runs" ("last_run");
CREATE UNIQUE INDEX "idx_value_enrichment_runs_run" ON "value_enrichment_runs" ("org_id", "value_hash", "module", "type");

CREATE TABLE "value_ip_ranges" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "value_id" bigint NOT NULL,
    "ip_start" bytea NOT NULL,
    "ip_end" bytea NOT NULL,
    "prefix" smallint NOT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "idx_value_ip_ranges_start_end" ON "value_ip_ranges" ("ip_start", "ip_end", "value_id");
CREATE UNIQUE INDEX "idx_value_ip_ranges_value_id" ON "value_ip_ranges" ("value_id");

CREATE TABLE "warninglists" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(255) NOT NULL,
    "type" varchar(255) DEFAULT 'string' NOT NULL,
    "description" text NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "enabled" boolean DEFAULT 'FALSE' NOT NULL,
    "default" boolean DEFAULT 'TRUE' NOT NULL,
    "category" varchar(20) DEFAULT 'false_positive' NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "warninglist_entries" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "value" text NOT NULL,
    "warninglist_id" bigint NOT NULL,
    "comment" text DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "idx_warninglist_entries_warninglist_id" ON "warninglist_entries" ("warninglist_id");
CREATE INDEX "idx_warn_values" ON "warninglist_entries" USING hash ("value");

CREATE TABLE "warninglist_types" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "type" varchar(255) NOT NULL,
    "warninglist_id" bigint NOT NULL,
    PRIMARY KEY ("id")
);

CREATE TABLE "workflows" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "uuid" varchar(40) NOT NULL,
    "name" varchar(191) NOT NULL,
    "description" varchar(191) NOT NULL,
    "timestamp" bigint DEFAULT 0 NOT NULL,
    "enabled" boolean DEFAULT 'FALSE' NOT NULL,
    "counter" integer DEFAULT 0 NOT NULL,
    "trigger_id" varchar(191) NOT NULL,
    "debug_enabled" boolean DEFAULT 'FALSE' NOT NULL,
    "data" text DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "idx_workflows_name" ON "workflows" ("name");
CREATE INDEX "idx_workflows_timestamp" ON "workflows" ("timestamp");
CREATE INDEX "idx_workflows_trigger_id" ON "workflows" ("trigger_id");
CREATE INDEX "idx_workflows_uuid" ON "workflows" ("uuid");

CREATE TABLE "workflow_blueprints" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "uuid" varchar(40) NOT NULL,
    "name" varchar(191) NOT NULL,
    "description" varchar(191) NOT NULL,
    "timestamp" bigint DEFAULT 0 NOT NULL,
    "default" boolean DEFAULT 'FALSE' NOT NULL,
    "data" text DEFAULT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "idx_workflow_blueprints_name" ON "workflow_blueprints" ("name");
CREATE INDEX "idx_workflow_blueprints_timestamp" ON "workflow_blueprints" ("timestamp");
CREATE INDEX "idx_workflow_blueprints_uuid" ON "workflow_blueprints" ("uuid");

