(1, '5000487b-3e75-46e4-8c43-96da9dc2268b', 'Administrator', 'A comprehensive site-administrator overview: live resource monitors (CPU, memory, disk), instance usage statistics, system health rollup, sync test and cache freshness, worker queues, mail log, recent logins, API activity, and the latest users to join. Visible to site admins only.', 'FALSE', 'TRUE', 0, 0, 0, 'perm_site_admin', '[{"instance_id":"w_1","widget":"UsageDataWidget","config":{"alias":"Usage"},"position":{"x":2,"y":6,"w":4,"h":3}},{"instance_id":"w_2","widget":"NewUsersWidget","config":{"alias":"Latest users","fields":["id","date_created","Organisation.name","email"]},"position":{"x":2,"y":0,"w":4,"h":6}},{"instance_id":"w_5","widget":"LoginsWidget","config":{"alias":"Logins this month"},"position":{"x":9,"y":4,"w":3,"h":3}},{"instance_id":"w_6","widget":"APIActivityWidget","config":{"alias":"API activity","filter":[]},"position":{"x":9,"y":7,"w":3,"h":3}},{"instance_id":"w_7","widget":"BenchmarkTopListWidget","config":{"alias":"","refresh_delay":"","days":"10","field":"sql_time"},"position":{"x":0,"y":9,"w":3,"h":6}},{"instance_id":"w_8","widget":"MispAdminSyncTestWidget","config":[],"position":{"x":6,"y":7,"w":3,"h":4}},{"instance_id":"w_10","widget":"MispAdminWorkerWidget","config":{"alias":"","refresh_delay":""},"position":{"x":9,"y":10,"w":3,"h":5}},{"instance_id":"w_11","widget":"CpuLoadMonitorWidget","config":{"alias":"","window":180,"interval":3},"position":{"x":0,"y":0,"w":2,"h":3}},{"instance_id":"w_12","widget":"MemoryUsageMonitorWidget","config":{"alias":"","window":180,"interval":3},"position":{"x":0,"y":3,"w":2,"h":3}},{"instance_id":"w_13","widget":"DiskUsageMonitorWidget","config":{"path":"","threshold":85},"position":{"x":0,"y":6,"w":2,"h":3}},{"instance_id":"w_14","widget":"LoggedInUsersWidget","config":[],"position":{"x":9,"y":0,"w":3,"h":4}},{"instance_id":"w_15","widget":"MispAdminHealthWidget","config":[],"position":{"x":6,"y":0,"w":3,"h":7}},{"instance_id":"w_16","widget":"MispCacheStatusWidget","config":[],"position":{"x":6,"y":11,"w":3,"h":4}},{"instance_id":"w_17","widget":"MispMailLogWidget","config":{"log_path":"","limit":20,"lookback_bytes":65536},"position":{"x":3,"y":9,"w":3,"h":6}}]', 1792347918),
(2, '0c6b496d-b6e7-43f3-be7f-2f30215c568c', 'Analyst', 'A threat-analyst starting point: the geographic spread of recent indicators and of threat-actor origins, a live attack map, ATT&CK technique coverage, trending vulnerabilities and threat actors, new-data stats for your time window, overlap with your organisation''s data, and the latest analyst notes, opinions, and event reports.', 'TRUE', 'TRUE', 0, 0, 0, '', '[{"instance_id":"w_3","widget":"AttributeGeoMapWidget","config":{"alias":"Recent geolocated indicators by country","time_window":"7d","limit":10000,"palette":"danger","projection":"naturalEarth","sources":["ip","domain_tld","asn","country_galaxy","threat_actor"]},"position":{"x":0,"y":7,"w":3,"h":4}},{"instance_id":"w_4","widget":"ThreatActorCountryMapWidget","config":{"alias":"Threat actor origins"},"position":{"x":3,"y":7,"w":3,"h":4}},{"instance_id":"w_8","widget":"AttackWidget","config":{"alias":"","time_window":"7d","filters":{"attackGalaxy":"mitre-attack-pattern","published":[0,1]}},"position":{"x":0,"y":11,"w":12,"h":6}},{"instance_id":"w_9","widget":"TrendingWidget","config":{"alias":"Trending vulnerabilities","dimension":"vulnerability","time_window":"7d","threshold":10,"min_count":3},"position":{"x":10,"y":2,"w":2,"h":5}},{"instance_id":"w_10","widget":"NewDataStatsWidget","config":{"alias":"New data within time window","time_window":"7d","country":"","sector":""},"position":{"x":0,"y":0,"w":12,"h":2}},{"instance_id":"w_12","widget":"TrendingWidget","config":{"alias":"Trending threat actors","dimension":"threat-actor","time_window":"7d","threshold":10,"min_count":3},"position":{"x":8,"y":2,"w":2,"h":5}},{"instance_id":"w_13","widget":"PewPewMapWidget","config":{"alias":"","time_window":"7d","mode":"webgl-globe","skin":"day","max_arcs":500},"position":{"x":6,"y":7,"w":2,"h":4}},{"instance_id":"w_15","widget":"OverlapWithMyOrgWidget","config":{"alias":"Correlations to my org''s data","time_window":"7d","exclude_own_org":true},"position":{"x":8,"y":7,"w":4,"h":4}},{"instance_id":"w_19","widget":"RecentAnalystDataWidget","config":{"alias":"Notes and Opinions","time_window":"7d","limit":10},"position":{"x":0,"y":2,"w":4,"h":5}},{"instance_id":"w_20","widget":"RecentEventReportsWidget","config":{"time_window":"7d","limit":10},"position":{"x":4,"y":2,"w":4,"h":5}}]', 1792347918),
(3, '2b50c003-c475-4c9c-ac90-0a177b44e565', 'Community', 'A sharing-community overview: where the member organisations are, who contributes most (orgs and users), how the community has grown, overall usage, and the sharing relationships between organisations.', 'FALSE', 'TRUE', 0, 0, 0, '', '[{"instance_id":"w_1","widget":"OrganisationMapWidget","config":{"alias":"Organisations by country"},"position":{"x":0,"y":0,"w":8,"h":5}},{"instance_id":"w_2","widget":"UsageDataWidget","config":{"alias":"Usage"},"position":{"x":8,"y":0,"w":4,"h":5}},{"instance_id":"w_3","widget":"OrgContributionToplistWidget","config":{"alias":"Top contributing organisations"},"position":{"x":0,"y":5,"w":6,"h":4}},{"instance_id":"w_4","widget":"UserContributionToplistWidget","config":{"alias":"Top contributing users"},"position":{"x":6,"y":5,"w":6,"h":4}},{"instance_id":"w_5","widget":"OrgsEvolutionWidget","config":{"alias":"Organisation growth"},"position":{"x":0,"y":9,"w":6,"h":6}},{"instance_id":"w_6","widget":"SharingGraphWidget","config":{"alias":"Sharing relationships"},"position":{"x":6,"y":9,"w":6,"h":6}}]', 1792347918)
